window.AUTH=window.AUTH||{};window.AUTH["02-1192"]={"d":"02-1192","id":"2004/02-1192","n":"Cooper Industries, Inc. v. Aviall Services, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioner","date":"","url":"https://www.justice.gov/osg/media/203566/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/cooper-industries-v-aviall-services-amicus-merits","n":94}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep543/usrep543157/usrep543157.pdf","tr":false,"items":[{"t":"case","label":"Akzo Coatings, Inc. v. Aigner Corp.","cite":"30 F.3d 761","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/30/761/","by":{"0":"6, 14"}},{"t":"case","label":"15 Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Atherton v. FDIC","cite":"519 U.S. 213","y":1997,"id":"1996/95-928","sc":1,"sum":"The unanimous Court concluded that \"state law sets the standard of conduct as long as the state standard is stricter than that of the federal statute.\" The opinion by Justice Stephen Breyer held that the federal \"gross negligence\" statute was only intended to set a \"floor\" or minimum standard for state laws governing negligent conduct.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Bedford Affiliates v. Sills","cite":"156 F.3d 416","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/156/416/","op":1,"by":{"0":"23"}},{"t":"case","label":"Centerior Serv. Co. v. Acme Scrap Iron & Metal Corp.","cite":"153 F.3d 344","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/153/344/","op":2,"by":{"0":"6, 14"}},{"t":"case","label":"City of Waukesha v. Viacom, Inc.","cite":"221 F. Supp. 2d 975","y":2002,"court":"E.D. Wis.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/221/975/","by":{"0":"10"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"op":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 23, 24"}},{"t":"case","label":"Control Data Corp. v. S.C.S.C. Corp.","cite":"53 F.3d 930","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/53/930/","by":{"0":"28"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"op":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"123 S. Ct. 1655","y":2003,"id":"2002/01-593","sc":1,"sum":"The Court held, 7-2, that a foreign state must itself own a majority of the shares of a corporation if the corporation is to be deemed an instrumentality of the state under the provisions of the FSIA and, 9-0, that instrumentality status is determined at the time of the filing of the complaint.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"E.I. DuPont De Nemours & Co. v. United States","cite":"2003 WL 23104700","y":2003,"court":"D.N.J. Dec. 30","by":{"0":"10"}},{"t":"case","label":"FMC Corp. v. Aero Indus., Inc.","cite":"998 F.2d 842","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/998/842/","by":{"0":"29"}},{"t":"case","label":"Federal Election Comm’n v. NRA Political Victory Fund","cite":"513 U.S. 88","y":1994,"id":"1994/93-1151","sc":1,"sum":"Petitioner Federal Election Commission (FEC) brought this civil action against respondents seeking to enforce a provision of the Federal Election Campaign Act of 1971 (FECA). The District Court ruled against respondents. The Court of Appeals reversed and entered its judgment on October 22, 1993. Without first seeking or obtaining the Solicitor General's authorization, the FEC filed in its own name a petition for a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"sum":"After respondent Mans filed for relief under Chapter 11 of the Bankruptcy Code, petitioners William and Norinne Field alleged, in effect, that letters Mans had written to them constituted fraudulent representations on which they relied in continuing to extend credit to a corporation controlled by Mans, and that, accordingly, Mans's obligation to them as guarantor of the corporation's debt should be excepted from …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 199","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Gonzaga Univ. v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"sum":"The Court held that such an action is foreclosed because the relevant provisions of FERPA create no personal rights to enforce.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Great-West Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Key Tronic Corp. v. United States","cite":"511 U.S. 809","y":1994,"id":"1993/93-376","sc":1,"op":15,"sum":"CERCLA § 107 does not provide for the award of private litigants' attorney's fees associated with bringing a cost recovery action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 14, 20, 29"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Lamie v. United States Trustee","cite":"124 S. Ct. 1023","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"13, 17, 23, 25"}},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"sum":"The Court held that a district court conducting pretrial proceedings pursuant to section 1407(a) has no authority to invoke section 1404(a) to assign a transferred case to itself for trial.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"515 U.S. 291","y":1995,"id":"1994/94-820","sc":1,"sum":"The Court held that a disability award may be modified under the LHWCA where there is a change in the employee's wage-earning capacity, even without any change in the employee's physical condition.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"New Castle County v. Halliburton NUS Corp.","cite":"111 F.3d 1116","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/111/1116/","op":2,"by":{"0":"17-18, 29"}},{"t":"case","label":"Pavelic & LeFlore v. Marvel Entm’t Group","cite":"493 U.S. 120","y":1989,"id":"1989/88-791","sc":1,"sum":"When read in the context of all of Rule ll's signature provisions, the phrase \"person who signed\" connotes the individual signer mentioned at the outset of the Rule and authorizes a court to impose a sanction only against that individual. That is so even when the individual explicitly signs on behalfof the firm, since it is only the signature \"in the attorney's individual name\" which complies with the Rule's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Pennsylvania v. Union Gas Co.","cite":"491 U.S. 1","y":1989,"id":"1988/87-1241","sc":1,"op":1,"sum":"The judgment is affirmed, and the case is remanded. 832 F. 2d 1343, affirmed and remanded. JUSTICE BRENNAN delivered the opinion of the Court with respect to Parts I and II, concluding that CERCLA, as amended by SARA, clearly expresses an intent to hold States liable in damages in federal court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Pinal Creek Group v. Newmont Mining Corp.","cite":"118 F.3d 1298","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/118/1298/","op":2,"by":{"0":"6, 20"}},{"t":"case","label":"Pneumo Abex Corp. v. High Point, Thomasville & Denton R.R.","cite":"142 F.3d 769","y":1998,"url":"https://www.courtlistener.com/c/F.3d/142/769/","op":1,"by":{"0":"6, 14"}},{"t":"case","label":"Redwing Carriers, Inc. v. Saraland Apartments","cite":"94 F.3d 1489","y":1996,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/94/1489/","op":1,"by":{"0":"19"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 29"}},{"t":"case","label":"Rumpke, Inc. v. Cummins Engine Co.","cite":"107 F.3d 1235","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/107/1235/","by":{"0":"20"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"sum":"The Court held that section 666(a)(1)(B) does not require the Government to prove the bribe in question had a demonstrated effect upon federal funds.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Shaw v. Railroad Co.","cite":"101 U.S. 557","y":1879,"id":"scdb/1879-108","sc":1,"sum":"This is an action of replevin brought by the Merchants’ National Bankof St. Louis, Missouri, against Shaw & Esrey, of Philadelphia, Pennsylvania, to recover possession of certain cotton, marked “ W D I.” One hundred and forty-one bales thereof having been taken possession of by the marshal were returned to the defendants upon their entering into the proper bond. On Nov. 11, 1874, Norvell & Co., of St. Louis, sold to …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Texas Indus., Inc. v. Radcliff Materials, Inc.","cite":"451 U.S. 630","y":1981,"id":"1980/79-1144","sc":1,"op":9,"sum":"There is no basis in federal statutory or common law for allowing federal courts to fashion the right to contribution urged by petitioner.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"1325 “G” Street Assocs. LP v. Rockwood Pigments NA, Inc.","cite":"235 F. Supp. 2d 458","y":2002,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/235/458/","by":{"0":"10"}},{"t":"case","label":"Transamerica Mortgage Advisors, Inc. v. Lewis","cite":"444 U.S. 11","y":1979,"id":"1978/77-1645","sc":1,"op":1,"sum":"Respondent, a shareholder of petitioner Mortgage Trust of America (Trust), brought this suit in Federal District Court as a derivative action on behalf of the Trust and as a class action on behalf of the Trust's shareholders, alleging that several trustees of the Trust, its investment adviser, and two corporations affiliated with the latter, had been guilty of various frauds and breaches of fiduciary duty in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"United States v. Aceto Agric. Chems. Corp.","cite":"872 F.2d 1373","y":1989,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/872/1373/","by":{"0":"14"}},{"t":"case","label":"United States v. Alcan Aluminum Corp.","cite":"990 F.2d 711","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/990/711/","by":{"0":"14"}},{"t":"case","label":"United States v. Alcan Aluminum Corp.","cite":"964 F.2d 252","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/964/252/","by":{"0":"14"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"sum":"But a corporate parent that actively participated in, and exercised control over, the operations of the facility itself may be held directly liable in its own right as an operator of the facility.","sumSrc":"Oyez","by":{"0":"2, 3, 13, 17"}},{"t":"case","label":"United States v. Colorado & E. R.R.","cite":"50 F.3d 1530","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/50/1530/","op":3,"by":{"0":"6, 14"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"United States v. Kayser-Roth Corp.","cite":"910 F.2d 24","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/910/24/","by":{"0":"14"}},{"t":"case","label":"United States v. Locke","cite":"529 U.S. 89","y":2000,"id":"1999/98-1701","sc":1,"sum":"The Court held that Washington's regulations regarding general navigation watch procedures, crew English-language skills and training, and maritime casualty reporting are pre-empted by the comprehensive federal regulatory scheme governing oil tankers. \"The State of Washington has enacted legislation in an area where the federal interest has been manifest since the beginning of our Republic and is now well established,\" wrote Justice Kennedy for the Court.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"United States v. Monsanto Co.","cite":"858 F.2d 160","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/858/160/","by":{"0":"14"}},{"t":"case","label":"United States v. R.W. Meyer, Inc.","cite":"889 F.2d 1497","y":1989,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/889/1497/","by":{"0":"14"}},{"t":"case","label":"United Techs. Corp. v. Browning-Ferris Indus.","cite":"33 F.3d 96","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/33/96/","op":1,"by":{"0":"6, 14, 16"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"0":"1, 4"}},{"t":"usc","label":"33 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/33/1321","subs":["(c)","(d)"],"by":{"0":"1, 4, 1, 4"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(9)","(14)","(20)","(23)","(26)","(29)","(31)"],"by":{"0":"1, 4, 3, 4, 3, 4, 3, 4, 3, 4, 3, 4, 3, 4, 3, 4"}},{"t":"usc","label":"42 U.S.C. § 9604","url":"https://www.law.cornell.edu/uscode/text/42/9604","subs":["(a)","(k)"],"by":{"0":"3, 4, passim, passim"}},{"t":"usc","label":"42 U.S.C. § 9605","url":"https://www.law.cornell.edu/uscode/text/42/9605","stext":{"head":"§9605. National contingency plan","paras":[[0,"(a) Revision and republication"],[0,"Within one hundred and eighty days after December 11, 1980, the President shall, after notice and opportunity for public comments, revise and republish the national contingency plan for the removal of oil and hazardous substances, originally prepared and published pursuant to section 1321 of title 33, to reflect and effectuate the responsibilities and powers created by this chapter, in addition to those matters specified in section 1321(c)(2) 1 of title 33. Such revision shall include a section of the plan to be known as the national hazardous substance response plan which shall establish procedures and standards for responding to releases of hazardous substances, pollutants, and contaminants, which shall include at a minimum:"],[1,"(1) methods for discovering and investigating facilities at which hazardous substances have been disposed of or otherwise come to be located;"],[1,"(2) methods for evaluating, including analyses of relative cost, and remedying any releases or threats of releases from facilities which pose substantial danger to the public health or the environment;"],[1,"(3) methods and criteria for determining the appropriate extent of removal, remedy, and other measures authorized by this chapter;"],[1,"(4) appropriate roles and responsibilities for the Federal, State, and local governments and for interstate and nongovernmental entities in effectuating the plan;"],[1,"(5) provision for identification, procurement, maintenance, and storage of response equipment and supplies;"],[1,"(6) a method for and assignment of responsibility for reporting the existence of such facilities which may be located on federally owned or controlled properties and any releases of hazardous substances from such facilities;"],[1,"(7) means of assuring that remedial action measures are cost-effective over the period of potential exposure to the hazardous substances or contaminated materials;"],[1,"(8)(A) criteria for determining priorities among releases or threatened releases throughout the United States for the purpose of taking remedial action and, to the extent practicable taking into account the potential urgency of such action, for the purpose of taking removal action. Criteria and priorities under this paragraph shall be based upon relative risk or danger to public health or welfare or the environment, in the judgment of the President, taking into account to the extent possible the population at risk, the hazard potential of the hazardous substances at such facilities, the potential for contamination of drinking water supplies, the potential for direct human contact, the potential for destruction of sensitive ecosystems, the damage to natural resources which may affect the human food chain and which is associated with any release or threatened release, the contamination or potential contamination of the ambient air which is associated with the release or threatened release, State preparedness to assume State costs and responsibilities, and other appropriate factors;"],[1,"(B) based upon the criteria set forth in subparagraph (A) of this paragraph, the President shall list as part of the plan national priorities among the known releases or threatened releases throughout the United States and shall revise the list no less often than annually. Within one year after December 11, 1980, and annually thereafter, each State shall establish and submit for consideration by the President priorities for remedial action among known releases and potential releases in that State based upon the criteria set forth in subparagraph (A) of this paragraph. In assembling or revising the national list, the President shall consider any priorities established by the States. To the extent practicable, the highest priority facilities shall be designated individually and shall be referred to as the \"top priority among known response targets\", and, to the extent practicable, shall include among the one hundred highest priority facilities one such facility from each State which shall be the facility designated by the State as presenting the greatest danger to public health or welfare or the environment among the known facilities in such State. A State shall be allowed to designate its highest priority facility only once. Other priority facilities or incidents may be listed singly or grouped for response priority purposes;"],[1,"(9) specified roles for private organizations and entities in preparation for response and in responding to releases of hazardous substances, including identification of appropriate qualifications and capacity therefor and including consideration of minority firms in accordance with subsection (f); and"],[1,"(10) standards and testing procedures by which alternative or innovative treatment technologies can be determined to be appropriate for utilization in response actions authorized by this chapter."],[0,"The plan shall specify procedures, techniques, materials, equipment, and methods to be employed in identifying, removing, or remedying releases of hazardous substances comparable to those required under section 1321(c)(2)(F) and (G) and (j)(1) of title 33. Following publication of the revised national contingency plan, the response to and actions to minimize damage from hazardous substances releases shall, to the greatest extent possible, be in accordance with the provisions of the plan. The President may, from time to time, revise and republish the national contingency plan."],[0,"(b) Revision of plan"],[0,"Not later than 18 months after the enactment of the Superfund Amendments and Reauthorization Act of 1986 [October 17, 1986], the President shall revise the National Contingency Plan to reflect the requirements of such amendments. The portion of such Plan known as \"the National Hazardous Substance Response Plan\" shall be revised to provide procedures and standards for remedial actions undertaken pursuant to this chapter which are consistent with amendments made by the Superfund Amendments and Reauthorization Act of 1986 relating to the selection of remedial action."],[0,"(c) Hazard ranking system"],[0,"(1) Revision"],[1,"Not later than 18 months after October 17, 1986, and after publication of notice and opportunity for submission of comments in accordance with section 553 of title 5, the President shall by rule promulgate amendments to the hazard ranking system in effect on September 1, 1984. Such amendments shall assure, to the maximum extent feasible, that the hazard ranking system accurately assesses the relative degree of risk to human health and the environment posed by sites and facilities subject to review. The President shall establish an effective date for the amended hazard ranking system which is not later than 24 months after October 17, 1986. Such amended hazard ranking system shall be applied to any site or facility to be newly listed on the National Priorities List after the effective date established by the President. Until such effective date of the regulations, the hazard ranking system in effect on September 1, 1984, shall continue in full force and effect."],[0,"(2) Health assessment of water contamination risks"],[1,"In carrying out this subsection, the President shall ensure that the human health risks associated with the contamination or potential contamination (either directly or as a result of the runoff of any hazardous substance or pollutant or contaminant from sites or facilities) of surface water are appropriately assessed where such surface water is, or can be, used for recreation or potable water consumption. In making the assessment required pursuant to the preceding sentence, the President shall take into account the potential migration of any hazardous substance or pollutant or contaminant through such surface water to downstream sources of drinking water."],[0,"(3) Reevaluation not required"],[1,"The President shall not be required to reevaluate, after October 17, 1986, the hazard ranking of any facility which was evaluated in accordance with the criteria under this section before the effective date of the amendments to the hazard ranking system under this subsection and which was assigned a national priority under the National Contingency Plan."],[0,"(4) New information"],[1,"Nothing in paragraph (3) shall preclude the President from taking new information into account in undertaking response actions under this chapter."],[0,"(d) Petition for assessment of release"],[0,"Any person who is, or may be, affected by a release or threatened release of a hazardous substance or pollutant or contaminant, may petition the President to conduct a preliminary assessment of the hazards to public health and the environment which are associated with such release or threatened release. If the President has not previously conducted a preliminary assessment of such release, the President shall, within 12 months after the receipt of any such petition, complete such assessment or provide an explanation of why the assessment is not appropriate. If the preliminary assessment indicates that the release or threatened release concerned may pose a threat to human health or the environment, the President shall promptly evaluate such release or threatened release in accordance with the hazard ranking system referred to in paragraph (8)(A) of subsection (a) to determine the national priority of such release or threatened release."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9605?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9605. National contingency plan","tname":"The Public Health and Welfare","by":{"0":"passim"}},{"t":"usc","label":"42 U.S.C. § 9606","url":"https://www.law.cornell.edu/uscode/text/42/9606","subs":["(a)","(b)","(b)(2)(B)"],"stext":{"head":"§9606. Abatement actions","paras":[[0,"(a) Maintenance, jurisdiction, etc."],[0,"In addition to any other action taken by a State or local government, when the President determines that there may be an imminent and substantial endangerment to the public health or welfare or the environment because of an actual or threatened release of a hazardous substance from a facility, he may require the Attorney General of the United States to secure such relief as may be necessary to abate such danger or threat, and the district court of the United States in the district in which the threat occurs shall have jurisdiction to grant such relief as the public interest and the equities of the case may require. The President may also, after notice to the affected State, take other action under this section including, but not limited to, issuing such orders as may be necessary to protect public health and welfare and the environment."],[0,"(b) Fines; reimbursement"],[0,"(1) Any person who, without sufficient cause, willfully violates, or fails or refuses to comply with, any order of the President under subsection (a) may, in an action brought in the appropriate United States district court to enforce such order, be fined not more than $25,000 for each day in which such violation occurs or such failure to comply continues."],[0,"(2)(A) Any person who receives and complies with the terms of any order issued under subsection (a) may, within 60 days after completion of the required action, petition the President for reimbursement from the Fund for the reasonable costs of such action, plus interest. Any interest payable under this paragraph shall accrue on the amounts expended from the date of expenditure at the same rate as specified for interest on investments of the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26."],[0,"(B) If the President refuses to grant all or part of a petition made under this paragraph, the petitioner may within 30 days of receipt of such refusal file an action against the President in the appropriate United States district court seeking reimbursement from the Fund."],[0,"(C) Except as provided in subparagraph (D), to obtain reimbursement, the petitioner shall establish by a preponderance of the evidence that it is not liable for response costs under section 9607(a) of this title and that costs for which it seeks reimbursement are reasonable in light of the action required by the relevant order."],[0,"(D) A petitioner who is liable for response costs under section 9607(a) of this title may also recover its reasonable costs of response to the extent that it can demonstrate, on the administrative record, that the President's decision in selecting the response action ordered was arbitrary and capricious or was otherwise not in accordance with law. Reimbursement awarded under this subparagraph shall include all reasonable response costs incurred by the petitioner pursuant to the portions of the order found to be arbitrary and capricious or otherwise not in accordance with law."],[0,"(E) Reimbursement awarded by a court under subparagraph (C) or (D) may include appropriate costs, fees, and other expenses in accordance with subsections (a) and (d) of section 2412 of title 28."],[0,"(c) Guidelines for using imminent hazard, enforcement, and emergency response authorities; promulgation by Administrator of EPA, scope, etc."],[0,"Within one hundred and eighty days after December 11, 1980, the Administrator of the Environmental Protection Agency shall, after consultation with the Attorney General, establish and publish guidelines for using the imminent hazard, enforcement, and emergency response authorities of this section and other existing statutes administered by the Administrator of the Environmental Protection Agency to effectuate the responsibilities and powers created by this chapter. Such guidelines shall to the extent practicable be consistent with the national hazardous substance response plan, and shall include, at a minimum, the assignment of responsibility for coordinating response actions with the issuance of administrative orders, enforcement of standards and permits, the gathering of information, and other imminent hazard and emergency powers authorized by (1) sections 1321(c)(2),1 1318, 1319, and 1364(a) of title 33, (2) sections 6927, 6928, 6934, and 6973 of this title, (3) sections 300j–4 and 300i of this title, (4) sections 7413, 7414, and 7603 of this title, and (5) section 2606 of title 15."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9606?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§9606. Abatement actions","tname":"The Public Health and Welfare","by":{"0":"passim, 3, 5, 22, 2, 4, 5, 6, 8, 20, 2, 4, 5, 6, 8, 20"}},{"t":"usc","label":"42 U.S.C. § 9607","url":"https://www.law.cornell.edu/uscode/text/42/9607","subs":["(a)","(a)(1)","(o)"],"stext":{"head":"§9607. Liability","paras":[[0,"(a) Covered persons; scope; recoverable costs and damages; interest rate; \"comparable maturity\" date"],[0,"Notwithstanding any other provision or rule of law, and subject only to the defenses set forth in subsection (b) of this section—"],[1,"(1) the owner and operator of a vessel or a facility,"],[1,"(2) any person who at the time of disposal of any hazardous substance owned or operated any facility at which such hazardous substances were disposed of,"],[1,"(3) any person who by contract, agreement, or otherwise arranged for disposal or treatment, or arranged with a transporter for transport for disposal or treatment, of hazardous substances owned or possessed by such person, by any other party or entity, at any facility or incineration vessel owned or operated by another party or entity and containing such hazardous substances, and"],[1,"(4) any person who accepts or accepted any hazardous substances for transport to disposal or treatment facilities, incineration vessels or sites selected by such person, from which there is a release, or a threatened release which causes the incurrence of response costs, of a hazardous substance, shall be liable for—"],[2,"(A) all costs of removal or remedial action incurred by the United States Government or a State or an Indian tribe not inconsistent with the national contingency plan;"],[2,"(B) any other necessary costs of response incurred by any other person consistent with the national contingency plan;"],[2,"(C) damages for injury to, destruction of, or loss of natural resources, including the reasonable costs of assessing such injury, destruction, or loss resulting from such a release; and"],[2,"(D) the costs of any health assessment or health effects study carried out under section 9604(i) of this title."],[0,"The amounts recoverable in an action under this section shall include interest on the amounts recoverable under subparagraphs (A) through (D). Such interest shall accrue from the later of (i) the date payment of a specified amount is demanded in writing, or (ii) the date of the expenditure concerned. The rate of interest on the outstanding unpaid balance of the amounts recoverable under this section shall be the same rate as is specified for interest on investments of the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26. For purposes of applying such amendments to interest under this subsection, the term \"comparable maturity\" shall be determined with reference to the date on which interest accruing under this subsection commences."],[0,"(b) Defenses"],[0,"There shall be no liability under subsection (a) of this section for a person otherwise liable who can establish by a preponderance of the evidence that the release or threat of release of a hazardous substance and the damages resulting therefrom were caused solely by—"],[1,"(1) an act of God;"],[1,"(2) an act of war;"],[1,"(3) an act or omission of a third party other than an employee or agent of the defendant, or than one whose act or omission occurs in connection with a contractual relationship, existing directly or indirectly, with the defendant (except where the sole contractual arrangement arises from a published tariff and acceptance for carriage by a common carrier by rail), if the defendant establishes by a preponderance of the evidence that (a) he exercised due care with respect to the hazardous substance concerned, taking into consideration the characteristics of such hazardous substance, in light of all relevant facts and circumstances, and (b) he took precautions against foreseeable acts or omissions of any such third party and the consequences that could foreseeably result from such acts or omissions; or"],[1,"(4) any combination of the foregoing paragraphs."],[0,"(c) Determination of amounts"],[0,"(1) Except as provided in paragraph (2) of this subsection, the liability under this section of an owner or operator or other responsible person for each release of a hazardous substance or incident involving release of a hazardous substance shall not exceed—"],[1,"(A) for any vessel, other than an incineration vessel, which carries any hazardous substance as cargo or residue, $300 per gross ton, or $5,000,000, whichever is greater;"],[1,"(B) for any other vessel, other than an incineration vessel, $300 per gross ton, or $500,000, whichever is greater;"],[1,"(C) for any motor vehicle, aircraft, hazardous liquid pipeline facility (as defined in section 60101(a) of title 49), or rolling stock, $50,000,000 or such lesser amount as the President shall establish by regulation, but in no event less than $5,000,000 (or, for releases of hazardous substances as defined in section 9601(14)(A) of this title into the navigable waters, $8,000,000). Such regulations shall take into account the size, type, location, storage, and handling capacity and other matters relating to the likelihood of release in each such class and to the economic impact of such limits on each such class; or"],[1,"(D) for any incineration vessel or any facility other than those specified in subparagraph (C) of this paragraph, the total of all costs of response plus $50,000,000 for any damages under this subchapter."],[0,"(2) Notwithstanding the limitations in paragraph (1) of this subsection, the liability of an owner or operator or other responsible person under this section shall be the full and total costs of response and damages, if (A)(i) the release or threat of release of a hazardous substance was the result of willful misconduct or willful negligence within the privity or knowledge of such person, or (ii) the primary cause of the release was a violation (within the privity or knowledge of such person) of applicable safety, construction, or operating standards or regulations; or (B) such person fails or refuses to provide all reasonable cooperation and assistance requested by a responsible public official in connection with response activities under the national contingency plan with respect to regulated carriers subject to the provisions of title 49 or vessels subject to the provisions of title 33 or 46, subparagraph (A)(ii) of this paragraph shall be deemed to refer to Federal standards or regulations."],[0,"(3) If any person who is liable for a release or threat of release of a hazardous substance fails without sufficient cause to properly provide removal or remedial action upon order of the President pursuant to section 9604 or 9606 of this title, such person may be liable to the United States for punitive damages in an amount at least equal to, and not more than three times, the amount of any costs incurred by the Fund as a result of such failure to take proper action. The President is authorized to commence a civil action against any such person to recover the punitive damages, which shall be in addition to any costs recovered from such person pursuant to section 9612(c) of this title. Any moneys received by the United States pursuant to this subsection shall be deposited in the Fund."],[0,"(d) Rendering care or advice"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), no person shall be liable under this subchapter for costs or damages as a result of actions taken or omitted in the course of rendering care, assistance, or advice in accordance with the National Contingency Plan (\"NCP\") or at the direction of an onscene coordinator appointed under such plan, with respect to an incident creating a danger to public health or welfare or the environment as a result of any releases of a hazardous substance or the threat thereof. This paragraph shall not preclude liability for costs or damages as the result of negligence on the part of such person."],[0,"(2) State and local governments"],[1,"No State or local government shall be liable under this subchapter for costs or damages as a result of actions taken in response to an emergency created by the release or threatened release of a hazardous substance generated by or from a facility owned by another person. This paragraph shall not preclude liability for costs or damages as a result of gross negligence or intentional misconduct by the State or local government. For the purpose of the preceding sentence, reckless, willful, or wanton misconduct shall constitute gross negligence."],[0,"(3) Savings provision"],[1,"This subsection shall not alter the liability of any person covered by the provisions of paragraph (1), (2), (3), or (4) of subsection (a) of this section with respect to the release or threatened release concerned."],[0,"(e) Indemnification, hold harmless, etc., agreements or conveyances; subrogation rights"],[0,"(1) No indemnification, hold harmless, or similar agreement or conveyance shall be effective to transfer from the owner or operator of any vessel or facility or from any person who may be liable for a release or threat of release under this section, to any other person the liability imposed under this section. Nothing in this subsection shall bar any agreement to insure, hold harmless, or indemnify a party to such agreement for any liability under this section."],[0,"(2) Nothing in this subchapter, including the provisions of paragraph (1) of this subsection, shall bar a cause of action that an owner or operator or any other person subject to liability under this section, or a guarantor, has or would have, by reason of subrogation or otherwise against any person."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9607?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§9607. Liability","tname":"The Public Health and Welfare","by":{"0":"2, 4, 5, 6, 8, 20, passim, 5, 11, 20, 21, 5, 11, 20, 21, 20, 21"}},{"t":"usc","label":"42 U.S.C. § 9613","url":"https://www.law.cornell.edu/uscode/text/42/9613","subs":["(f)(3)(B)","(g)","(g)(3)","(g)(3)(A)","(g)(3)(B)","(h)"],"stext":{"head":"§9613. Civil proceedings","paras":[[0,"(a) Review of regulations in Circuit Court of Appeals of the United States for the District of Columbia"],[0,"Review of any regulation promulgated under this chapter may be had upon application by any interested person only in the Circuit Court of Appeals of the United States for the District of Columbia. Any such application shall be made within ninety days from the date of promulgation of such regulations. Any matter with respect to which review could have been obtained under this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement or to obtain damages or recovery of response costs."],[0,"(b) Jurisdiction; venue"],[0,"Except as provided in subsections (a) and (h) of this section, the United States district courts shall have exclusive original jurisdiction over all controversies arising under this chapter, without regard to the citizenship of the parties or the amount in controversy. Venue shall lie in any district in which the release or damages occurred, or in which the defendant resides, may be found, or has his principal office. For the purposes of this section, the Fund shall reside in the District of Columbia."],[0,"(c) Controversies or other matters resulting from tax collection or tax regulation review"],[0,"The provisions of subsections (a) and (b) of this section shall not apply to any controversy or other matter resulting from the assessment of collection of any tax, as provided by subchapter II 1 of this chapter, or to the review of any regulation promulgated under title 26."],[0,"(d) Litigation commenced prior to December 11, 1980"],[0,"No provision of this chapter shall be deemed or held to moot any litigation concerning any release of any hazardous substance, or any damages associated therewith, commenced prior to December 11, 1980."],[0,"(e) Nationwide service of process"],[0,"In any action by the United States under this chapter, process may be served in any district where the defendant is found, resides, transacts business, or has appointed an agent for the service of process."],[0,"(f) Contribution"],[0,"(1) Contribution"],[1,"Any person may seek contribution from any other person who is liable or potentially liable under section 9607(a) of this title, during or following any civil action under section 9606 of this title or under section 9607(a) of this title. Such claims shall be brought in accordance with this section and the Federal Rules of Civil Procedure, and shall be governed by Federal law. In resolving contribution claims, the court may allocate response costs among liable parties using such equitable factors as the court determines are appropriate. Nothing in this subsection shall diminish the right of any person to bring an action for contribution in the absence of a civil action under section 9606 of this title or section 9607 of this title."],[0,"(2) Settlement"],[1,"A person who has resolved its liability to the United States or a State in an administrative or judicially approved settlement shall not be liable for claims for contribution regarding matters addressed in the settlement. Such settlement does not discharge any of the other potentially liable persons unless its terms so provide, but it reduces the potential liability of the others by the amount of the settlement."],[0,"(3) Persons not party to settlement"],[1,"(A) If the United States or a State has obtained less than complete relief from a person who has resolved its liability to the United States or the State in an administrative or judicially approved settlement, the United States or the State may bring an action against any person who has not so resolved its liability."],[1,"(B) A person who has resolved its liability to the United States or a State for some or all of a response action or for some or all of the costs of such action in an administrative or judicially approved settlement may seek contribution from any person who is not party to a settlement referred to in paragraph (2)."],[1,"(C) In any action under this paragraph, the rights of any person who has resolved its liability to the United States or a State shall be subordinate to the rights of the United States or the State. Any contribution action brought under this paragraph shall be governed by Federal law."],[0,"(g) Period in which action may be brought"],[0,"(1) Actions for natural resource damages"],[1,"Except as provided in paragraphs (3) and (4), no action may be commenced for damages (as defined in section 9601(6) of this title) under this chapter, unless that action is commenced within 3 years after the later of the following:"],[2,"(A) The date of the discovery of the loss and its connection with the release in question."],[2,"(B) The date on which regulations are promulgated under section 9651(c) of this title."],[1,"With respect to any facility listed on the National Priorities List (NPL), any Federal facility identified under section 9620 of this title (relating to Federal facilities), or any vessel or facility at which a remedial action under this chapter is otherwise scheduled, an action for damages under this chapter must be commenced within 3 years after the completion of the remedial action (excluding operation and maintenance activities) in lieu of the dates referred to in subparagraph (A) or (B). In no event may an action for damages under this chapter with respect to such a vessel or facility be commenced (i) prior to 60 days after the Federal or State natural resource trustee provides to the President and the potentially responsible party a notice of intent to file suit, or (ii) before selection of the remedial action if the President is diligently proceeding with a remedial investigation and feasibility study under section 9604(b) of this title or section 9620 of this title (relating to Federal facilities). The limitation in the preceding sentence on commencing an action before giving notice or before selection of the remedial action does not apply to actions filed on or before October 17, 1986."],[0,"(2) Actions for recovery of costs"],[1,"An initial action for recovery of the costs referred to in section 9607 of this title must be commenced—"],[2,"(A) for a removal action, within 3 years after completion of the removal action, except that such cost recovery action must be brought within 6 years after a determination to grant a waiver under section 9604(c)(1)(C) of this title for continued response action; and"],[2,"(B) for a remedial action, within 6 years after initiation of physical on-site construction of the remedial action, except that, if the remedial action is initiated within 3 years after the completion of the removal action, costs incurred in the removal action may be recovered in the cost recovery action brought under this subparagraph."],[1,"In any such action described in this subsection, the court shall enter a declaratory judgment on liability for response costs or damages that will be binding on any subsequent action or actions to recover further response costs or damages. A subsequent action or actions under section 9607 of this title for further response costs at the vessel or facility may be maintained at any time during the response action, but must be commenced no later than 3 years after the date of completion of all response action. Except as otherwise provided in this paragraph, an action may be commenced under section 9607 of this title for recovery of costs at any time after such costs have been incurred."],[0,"(3) Contribution"],[1,"No action for contribution for any response costs or damages may be commenced more than 3 years after—"],[2,"(A) the date of judgment in any action under this chapter for recovery of such costs or damages, or"],[2,"(B) the date of an administrative order under section 9622(g) of this title (relating to de minimis settlements) or 9622(h) of this title (relating to cost recovery settlements) or entry of a judicially approved settlement with respect to such costs or damages."],[0,"(4) Subrogation"],[1,"No action based on rights subrogated pursuant to this section by reason of payment of a claim may be commenced under this subchapter more than 3 years after the date of payment of such claim."],[0,"(5) Actions to recover indemnification payments"],[1,"Notwithstanding any other provision of this subsection, where a payment pursuant to an indemnification agreement with a response action contractor is made under section 9619 of this title, an action under section 9607 of this title for recovery of such indemnification payment from a potentially responsible party may be brought at any time before the expiration of 3 years from the date on which such payment is made."],[0,"(6) Minors and incompetents"],[1,"The time limitations contained herein shall not begin to run—"],[2,"(A) against a minor until the earlier of the date when such minor reaches 18 years of age or the date on which a legal representative is duly appointed for such minor, or"],[2,"(B) against an incompetent person until the earlier of the date on which such incompetent's incompetency ends or the date on which a legal representative is duly appointed for such incompetent."],[0,"(h) Timing of review"],[0,"No Federal court shall have jurisdiction under Federal law other than under section 1332 of title 28 (relating to diversity of citizenship jurisdiction) or under State law which is applicable or relevant and appropriate under section 9621 of this title (relating to cleanup standards) to review any challenges to removal or remedial action selected under section 9604 of this title, or to review any order issued under section 9606(a) of this title, in any action except one of the following:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9613?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§9613. Civil proceedings","tname":"The Public Health and Welfare","by":{"0":"20, 21, passim, passim, 7, 21, 27, 28, 27, 7, 11, 19, 21, 11, 21, 22, 22, 22, 7, 22"}},{"t":"usc","label":"42 U.S.C. § 9622","url":"https://www.law.cornell.edu/uscode/text/42/9622","subs":["(a)","(d)","(g)","(h)","(i)"],"by":{"0":"7, 22, 7, 22, 7, 22, 7, 22, 7, 22, 27"}},{"t":"usc","label":"42 U.S.C. § 9628","url":"https://www.law.cornell.edu/uscode/text/42/9628","subs":["(a)","(b)"],"by":{"0":"27, 27"}},{"t":"reg","label":"3 C.F.R. pt. 193","url":"https://www.ecfr.gov/current/title-3/part-193","by":{"0":"1, 3"}},{"t":"rule","label":"Fed. R. Civ. P. 2","url":"https://www.law.cornell.edu/rules/frcp/rule_2","by":{"0":"23"}}]};